S=/workspace/nox/web/site; cd $S
echo '' | base64 -d | gunzip > nox-news-x.js
echo '' | base64 -d | gunzip > nox-news-x.css
[ -f nav.json.bak_w3_1 ] || cp nav.json nav.json.bak_w3_1
python3 - <<'P'
import re,json
S='/workspace/nox/web/site/'
s=open(S+'index.html',encoding='utf-8').read()
head=s[:s.index('<body')].replace('ГЛАВНАЯ','НОВОСТИ').replace('<link rel="stylesheet" href="./nox-unify.css">','<link rel="stylesheet" href="./nox-unify.css">\n<link rel="stylesheet" href="./nox-news-x.css?v=1">')
head=re.sub(r'<link rel="stylesheet" href="./nox-home-x.css[^>]*>\n?','',head)
body='''<body data-page="news" class="boot">
<div id="app">
<main class="page" id="page"><div class="wrap">
<div class="ph"><div><span class="kick mono">Лента FreshRSS · главная новость и сводка NOX</span><h1>Новости</h1></div></div>
<div id="nwX"></div>
</div></main>
</div>
<script type="module" src="./nox-nav.js"></script>
<script type="module" src="./nox-news-x.js?v=1"></script>
<script src="nav-extra.js" defer></script>
<script src="./nox-dock-pop.js" defer></script>
<script type="module" src="./nox-ninja.js"></script>
<script src="./nox-minichat.js" defer></script>
<link rel="manifest" href="./manifest.json"><script src="./nox-pwa.js" defer></script>
</body>
</html>
'''
open(S+'news.html','w',encoding='utf-8').write(head+body)
d=json.load(open(S+'nav.json',encoding='utf-8'))
have={i['file'] for g in d['groups'] for i in g['items']}
g=[g for g in d['groups'] if g['group']=='ЗНАНИЯ'][0]
for f,t in (('news.html','NOX HELION · НОВОСТИ'),('events.html','NOX HELION · СОБЫТИЯ')):
    if f not in have: g['items'].append({'file':f,'title':t,'soon':False}); print('added',f)
json.dump(d,open(S+'nav.json','w',encoding='utf-8'),ensure_ascii=False)
P
/workspace/nox/venv/bin/python /workspace/nox/qa_ctl.py --pin 2>&1 | tail -3
echo '' | base64 -d | gunzip > /tmp/w3s.py
